-- V4-16 R23 isolated engineering migration V1; never production apply.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS shadow_source_readiness_receipts(id TEXT PRIMARY KEY, namespace TEXT NOT NULL CHECK(namespace='SHADOW_V4'), evidence_origin TEXT NOT NULL CHECK(evidence_origin='ENGINEERING_FIXTURE'), payload TEXT NOT NULL CHECK(json_valid(payload)), digest TEXT NOT NULL CHECK(length(digest)=64));
CREATE TRIGGER IF NOT EXISTS shadow_source_readiness_receipts_no_update BEFORE UPDATE ON shadow_source_readiness_receipts BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS shadow_source_readiness_receipts_no_delete BEFORE DELETE ON shadow_source_readiness_receipts BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
