CREATE TRIGGER IF NOT EXISTS shadow_observation_slots_no_update BEFORE UPDATE ON shadow_observation_slots BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER IF NOT EXISTS shadow_observation_slots_no_delete BEFORE DELETE ON shadow_observation_slots BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
